rng=np.random.default_rng(1601);r=rng.normal(0,0.012,120);p=500*np.exp(np.cumsum(r));ax.plot(p,color=ACCENT,label='SPY-like price (USD)');ax2=ax.twinx();ax2.plot(r*100,color=WARM,alpha=.75,label='daily log return (%)');ax.set_xlabel('trading day');ax.set_ylabel('price (USD)');ax2.set_ylabel('return (%)');ax.set_title('Levels can drift; returns are the diagnostic series',loc='left');ax.grid(alpha=.2)
